{"name": "file_write", "arguments": {"path": "schedule_solver_fixed.py", "content": "#!/usr/bin/env python3
"""
会议安排约束满足问题求解器（修复版）
"""

import json

def time_to_minutes(t):
    hour, minute = map(int, t.split(":"))
    return hour * 60 + minute

def minutes_to_time(m):
    return f"{m//60:02d}:{m%60:02d}"

def check_constraints(schedule):
    """检查所有约束是否满足"""
    meetings = schedule

    # 约束 1: 工作时间：9:00-18:00（共 9 小时）
    for meeting in meetings:
        start = time_to_minutes(meeting["start_time"])
        end = time_to_minutes(meeting["end_time"])
        if start < 9*60 or end > 18*60:
            return False, f"会议 {meeting['meeting']} 不在工作时间内"

    # 约束 2: 每个人同一时间只能参加一个会议
    people = {}
    for meeting in meetings:
        for person in meeting["participants"]:
            if person not in people:
                people[person] = []
            people[person].append({
                "start": time_to_minutes(meeting["start_time"]),
                "end": time_to_minutes(meeting["end_time"]),
                "meeting": meeting["meeting"]
            })

    for person, person_meetings in people.items():
        # 按开始时间排序
        person_meetings.sort(key=lambda x: x["start"])
        for i in range(len(person_meetings)-1):
            if person_meetings[i]["end"] > person_meetings[i+1]["start"]:
                return False, f"{person} 同时参加多个会议"

    # 约束 3: Alice 必须在下午（14:00 后）参加 Product Review
    for meeting in meetings:
        if meeting["meeting"] == "Product Review":
            if "Alice" not in meeting["participants"]:
                return False, "Product Review 没有 Alice"
            if time_to_minutes(meeting["start_time"]) < 14*60:
                return False, "Product Review 不在下午（14:00后）"

    # 约束 4: Bob 在 11:00-14:00 之间不可用
    for meeting in meetings:
        if "Bob" in meeting["participants"]:
            start = time_to_minutes(meeting["start_time"])
            end = time_to_minutes(meeting["end_time"])
            # 检查会议是否与11:00-14:00有重叠
            if start < 14*60 and end > 11*60:
                return False, f"Bob 在不可用时间参加 {meeting['meeting']}"

    # 约束 5: Eve 必须在上午（12:00 前）参加 Client Demo
    for meeting in meetings:
        if meeting["meeting"] == "Client Demo":
            if "Eve" not in meeting["participants"]:
                return False, "Client Demo 没有 Eve"
            if time_to_minutes(meeting["start_time"]) >= 12*60:
                return False, "Client Demo 不在上午（12:00前）"

    # 约束 6: Budget Planning 必须在 Tech Design 之前
    budget_time = None
    tech_time = None
    for meeting in meetings:
        if meeting["meeting"] == "Budget Planning":
            budget_time = time_to_minutes(meeting["start_time"])
        if meeting["meeting"] == "Tech Design":
            tech_time = time_to_minutes(meeting["start_time"])

    if budget_time is None or tech_time is None:
        return False, "缺少 Budget Planning 或 Tech Design"
    if budget_time >= tech_time:
        return False, "Budget Planning 不在 Tech Design 之前"

    # 约束 7: 每个会议之间至少间隔 30 分钟
    for i in range(len(meetings)):
        for j in range(i+1, len(meetings)):
            m1_start = time_to_minutes(meetings[i]["start_time"])
            m1_end = time_to_minutes(meetings[i]["end_time"])
            m2_start = time_to_minutes(meetings[j]["start_time"])
            m2_end = time_to_minutes(meetings[j]["end_time"])

            # 检查是否有重叠或间隔小于30分钟
            if not (m1_end + 30 <= m2_start or m2_end + 30 <= m1_start):
                return False, f"会议 {meetings[i]['meeting']} 和 {meetings[j]['meeting']} 间隔小于30分钟"

    # 约束 8: 会议室只有 2 个，不能同时开 3 个会议
    # 由于我们确保会议间隔至少30分钟，这个约束自动满足
    # 但还是要检查一下
    timeline = []
    for meeting in meetings:
        start = time_to_minutes(meeting["start_time"])
        end = time_to_minutes(meeting["end_time"])
        timeline.append((start, end, meeting["meeting"], meeting["room"]))

    # 检查每个时间点的并发会议数
    for minute in range(9*60, 18*60, 5):  # 每5分钟检查一次
        concurrent = 0
        for start, end, _, _ in timeline:
            if start <= minute < end:
                concurrent += 1
        if concurrent > 2:
            return False, f"在 {minutes_to_time(minute)} 有 {concurrent} 个会议同时进行"

    return True, "所有约束满足"

def find_solution():
    """手动寻找解决方案"""
    # 定义可能的开始时间（每30分钟）
    possible_times = []
    for hour in range(9, 18):
        for minute in [0, 30]:
            if hour == 17 and minute == 30:
                continue
            time_str = f"{hour:02d}:{minute:02d}"
            if time_to_minutes(time_str) + 60 <= 18*60:
                possible_times.append(time_str)

    print(f"可能的开始时间: {possible_times}")

    # 尝试一个合理的安排
    # 首先安排有严格时间约束的会议

    # 约束 5: Client Demo 必须在上午（12:00前），有 Eve 参加
    # 选择 10:00-11:00 或 11:00-12:00

    # 约束 3: Product Review 必须在下午（14:00后），有 Alice 参加
    # 选择 14:00-15:00 或之后

    # 约束 4: Bob 在 11:00-14:00 不可用
    # Bob 参加的会议：Product Review (下午) 和 Tech Design
    # 所以 Tech Design 必须在 11:00前 或 14:00后

    # 约束 6: Budget Planning 必须在 Tech Design 之前

    # 让我们尝试以下安排：
    # 1. Client Demo: 10:00-11:00 (上午，有 Eve)
    # 2. Budget Planning: 11:30-12:30 (在 Tech Design 之前)
    # 3. Tech Design: 15:00-16:00 (Bob 在 14:00后可用)
    # 4. Product Review: 14:00-15:00 (下午，有 Alice)
    # 5. Team Sync: 16:30-17:30

    # 检查人员冲突：
    # - Alice: Budget Planning (11:30-12:30), Product Review (14:00-15:00) ✓ 无冲突
    # - Bob: Tech Design (15:00-16:00), Product Review (14:00-15:00) ✗ 有冲突！14:00-15:00 和 15:00-16:00 是连续的但无重叠
    # - Carol: Product Review (14:00-15:00), Team Sync (16:30-17:30) ✓
    # - David: Tech Design (15:00-16:00), Team Sync (16:30-17:30) ✓
    # - Eve: Client Demo (10:00-11:00), Tech Design (15:00-16:00) ✓
    # - Frank: Budget Planning (11:30-12:30), Client Demo (10:00-11:00) ✓
    # - Grace: Budget Planning (11:30-12:30) ✓
    # - Henry: Team Sync (16:30-17:30), Client Demo (10:00-11:00) ✓

    # 调整：Product Review 和 Tech Design 都包含 Bob，需要间隔开
    # 让我们尝试：
    # 1. Client Demo: 09:00-10:00
    # 2. Budget Planning: 10:30-11:30
    # 3. Product Review: 14:00-15:00
    # 4. Tech Design: 15:30-16:30
    # 5. Team Sync: 17:00-18:00

    schedule = [
        {
            "meeting": "Client Demo",
            "start_time": "09:00",
            "end_time": "10:00",
            "room": "A",
            "participants": ["Eve", "Frank", "Henry"]
        },
        {
            "meeting": "Budget Planning",
            "start_time": "10:30",
            "end_time": "11:30",
            "room": "B",
            "participants": ["Alice", "Frank", "Grace"]
        },
        {
            "meeting": "Product Review",
            "start_time": "14:00",
            "end_time": "15:00",
            "room": "A",
            "participants": ["Alice", "Bob", "Carol"]
        },
        {
            "meeting": "Tech Design",
            "start_time": "15:30",
            "end_time": "16:30",
            "room": "B",
            "participants": ["Bob", "David", "Eve"]
        },
        {
            "meeting": "Team Sync",
            "start_time": "17:00",
            "end_time": "18:00",
            "room": "A",
            "participants": ["Carol", "David", "Henry"]
        }
    ]

    # 检查约束
    valid, message = check_constraints(schedule)

    if valid:
        print("方案通过所有约束检查！")
        return schedule
    else:
        print(f"方案有问题: {message}")
        return None

def main():
    print("寻找会议安排方案...")

    solution = find_solution()

    if solution:
        print("\n找到的解决方案:")
        for item in solution:
            print(f"{item['meeting']}: {item['start_time']}-{item['end_time']} (Room {item['room']}) - {item['participants']}")

        # 保存到JSON文件
        with open("schedule.json", "w") as f:
            json.dump(solution, f, indent=2)
        print("\n已保存到 schedule.json")

        # 验证所有约束
        print("\n验证所有约束:")
        valid, message = check_constraints(solution)
        if valid:
            print("✅ 所有约束满足！")
        else:
            print(f"❌ 约束检查失败: {message}")
    else:
        print("未找到满足所有约束的解决方案")

if __name__ == "__main__":
    main()"}}
